import{b as e,O as t,g as c,j as l}from"./chunks/framework.DcaUmd3X.js";const n=JSON.parse('{"title":"明朝那些事儿","description":"","frontmatter":{},"headers":[],"relativePath":"reading/digital/ming-dynasty/index.md","filePath":"读书感悟/电子书架/41.明朝那些事儿.md","lastUpdated":1781614933000}'),p={name:"reading/digital/ming-dynasty/index.md"};function u(b,o,k,q,a,d){return t(),c("div",null,[...o[0]||(o[0]=[l('<h1 id="明朝那些事儿" tabindex="-1">明朝那些事儿 <a class="header-anchor" href="#明朝那些事儿" aria-label="Permalink to &quot;明朝那些事儿&quot;">​</a></h1><p><code>当年明月</code> <code>历史</code></p><h2 id="书摘" tabindex="-1">书摘 <a class="header-anchor" href="#书摘" aria-label="Permalink to &quot;书摘&quot;">​</a></h2><blockquote><p>📌 所谓仁不带兵、义不行贾，冷酷不是残忍，不是杀戮无辜的老百姓，而是坚忍</p></blockquote><blockquote><p>📌 但正如俗话所说，锋芒自有毕现之日，强盛于东方之中国的光辉是无法掩盖的，当它的先进和文明为世界所公认之时，威服四海的时刻自然也就到来了。</p></blockquote><blockquote><p>📌 绢帕蘑菇及线香，本资民用反为殃。清风两袖朝天去，免得闾阎话短长！</p></blockquote><blockquote><p>📌 太师不贪财物，是男子汉，必当名垂青史，万世传颂（好男子，垂史册，颂扬万世）！</p></blockquote><blockquote><p>📌 这下王家更是了不得，王华的责任感也大大增强，毕竟老子英雄儿好汉，自己已经是状元了，儿子将来就算不能超过自己做个好汉，也不能当笨蛋。于是他请了很多老师来教王守仁读书。十岁的王守仁开始读四书五经了，他领悟很快，能举一反三，其聪明程度让老先生们也倍感惊讶，可是不久之后，老师们就发现了不好的苗头。据老师们向王状元反映，王守仁不是个好学生，不在私塾里坐着，却喜欢舞枪弄棍，读兵书，还喜欢问一些稀奇古怪的问题，写一些莫名其妙的东西，有诗为证：山近月远觉月小，便道此山大于月。若人有眼大如天，当见山高月更阔。</p></blockquote><blockquote><p>📌 士不可以不弘毅，任重而道远！仁以为己任，不亦重乎！死而后已，不亦远乎！</p></blockquote><blockquote><p>📌 知我者谓我心忧，不知我者谓我何求！</p></blockquote><blockquote><p>📌 懂得道理是重要的，但实际运用也是重要的！</p></blockquote><blockquote><p>📌 别人笑我太疯癫，我笑他人看不穿。不见五陵豪杰墓，无花无酒锄作田。</p></blockquote><blockquote><p>📌 “此心不动，随机而行。”</p></blockquote><blockquote><p>📌 “四方英杰，各有异同，议论纷纷，多言何益？”</p></blockquote><blockquote><p>📌 无善无恶心之体，有善有恶意之动。知善知恶是良知，为善去恶是格物。</p></blockquote><blockquote><p>📌 “天地虽大，但有一念向善，心存良知，虽凡夫俗子，皆可为圣贤！”</p></blockquote><blockquote><p>📌 滚滚长江东逝水，浪花淘尽英雄，是非成败转头空，青山依旧在，几度夕阳红。白发渔樵江渚上，惯看秋月春风，一壶浊酒喜相逢，古今多少事，都付笑谈中！</p></blockquote><blockquote><p>📌 没有竞争的市场只存在于理论想象之中。</p></blockquote><blockquote><p>📌 利益，只有充足的利益，才有驱动人们的魔力，这就是这个世界的真实面目，极其的残酷，却异常的真实。</p></blockquote><blockquote><p>📌 以天下为己任者，是然。</p></blockquote><blockquote><p>📌 以天下为己任，岂计个人荣辱！</p></blockquote><blockquote><p>📌 小筑暂高枕，忧时旧有盟。呼樽来揖客，挥麈坐谈兵。云护牙签满，星含宝剑横。封侯非我意，但愿海波平。</p></blockquote><blockquote><p>📌 疾如风，徐如林；侵掠如火，不动如山；难知如阴，动如雷震。</p></blockquote><blockquote><p>📌 据说拍马屁这个行当，最高境界是两句古诗，所谓“随风潜入夜，润物细无声”，在我看来，申时行做到了。</p></blockquote><blockquote><p>📌 夫攻不足者守有余，度彼之才，恢复固未易言，令专任之，犹足以慎固封守。”</p></blockquote><blockquote><p>📌 但他看了看我，说：“我说的没钱，不是没有收入，是没钱。”</p></blockquote><blockquote><p>📌 估计是历经考验，外加焕发第二次生命的激动，民军的战斗力越来越强，原本是被追着跑，现在个把能打的，都敢追着官兵跑。比如陕西著名悍将贺人龙，原本是去打李自成，结果被李自成打得落花流水，还围了起来，足足四十多天，断其粮食劝他投降，搞得贺总兵差点儿去啃树皮，差点没撑过来。到崇祯八年(1635)，中原和西北，基本是全乱了，这么下去，不用等清兵入关，大明可以直接关门。好在崇祯同志脑子转得快，随即派出了王牌——洪承畴。在当时，能干这活的，也就洪承畴了，这个人是彻头彻尾的实用主义者，手狠且心黑，对于当前时局，他的指导思想只有一字——杀。</p></blockquote><blockquote><p>📌 能改的，叫做缺点；不能改的，叫做弱点。</p></blockquote>',28)])])}const i=e(p,[["render",u]]);export{n as __pageData,i as default};
